        if not mypositions:
            # Play on my starter edge, preferably closest to the center
            if player_idx==1:
                edge_moves = [pos for pos in valid_positions if pos[1]==1]
            else:
                edge_moves = [pos for pos in valid_positions if pos[0]==1]
            # choose central among possible moves for maximal flexibility
