    def parse_hint(self, hint: str):
        # Returns: (operation, condition, arguments)
        # Ex: sum is less than 6   =>  ('sum','is less than', [6])
        # Ex: product contains digit 6 => ('product','contains digit', [6])
        op = None
        if hint.startswith('sum'):
            op = 'sum'
            rest = hint[3:].strip()
        elif hint.startswith('product'):
            op = 'product'
            rest = hint[7:].strip()
        elif hint.startswith('difference'):
            op = 'difference'
            rest = hint[10:].strip()
        else:
            op = None
            rest = hint
        rest = rest.strip()
        # Find out condition and argument(s)
        # Check known patterns
        if rest.startswith('is less than'):
            val = int(re.findall(r'is less than (\d+)', rest)[0])
            return (op, 'lt', [val])
        elif rest.startswith('is greater than'):
            val = int(re.findall(r'is greater than (\d+)', rest)[0])
            return (op, 'gt', [val])
        elif rest.startswith('contains digit'):
            val = int(re.findall(r'contains digit (\d+)', rest)[0])
            return (op, 'contains_digit', [val])
        elif rest.startswith('is even'):
            return (op, 'is_even', [])
        elif rest.startswith('is odd'):
            return (op, 'is_odd', [])
        elif rest.startswith('is between'):
            matched = re.findall(r'is between (\d+) and (\d+), inclusive', rest)
            if matched:
                v1, v2 = matched[0]
                return (op, 'between', [int(v1), int(v2)])
        # Unknown case (defaults to pass)  
        return (op, None, [])

    def compute_op(self, op: str, row: int, col: int) -> int:
        if op == 'sum':
            return row + col
        elif op == 'product':
            return row * col
        elif op == 'difference':
            return abs(row - col)
        return 0

    def satisfies(self, op: str, cond: str, args: List, row: int, col: int) -> bool:
        val = self.compute_op(op, row, col)
        if cond == 'lt':
            return val < args[0]
        elif cond == 'gt':
            return val > args[0]
        elif cond == 'contains_digit':
            return str(args[0]) in str(val)
        elif cond == 'is_even':
            return val % 2 == 0
        elif cond == 'is_odd':
            return val % 2 == 1
        elif cond == 'between':
            return args[0] <= val <= args[1]
        return False

    def get_unoccupied_hint_positions(self, grid: List[List[int]], op: str, cond: str, args: List) -> List[Tuple[int, int]]:
        rs = len(grid)
