from pydantic import BaseModel
from typing import List, Optional, Dict, Any, Tuple
from enum import Enum
from abc import abstractmethod
import re

from system.message import Info
from system.message import BaseMessageDataType
from model.strategy_type import StrategyType
from model.base import BaseStrategy

#---------------- HELPER FUNCTIONS ----------------------

def parse_hint(hint_str: str):
    # Returns: (operation:str, condition:str, v1, v2)
    m = re.match(r"(sum|product|difference) ([^,]+)(?:, inclusive)?(?: (\d+))?(?: and (\d+))?", hint_str)
    if not m:
        # fallback: just split
        tokens = hint_str.split()
        operation = tokens[0]
        condition = ' '.join(tokens[1:])
        v1 = v2 = None
        return operation, condition, v1, v2
    operation = m.group(1)
    cond = m.group(2).strip()
    v1 = m.group(3)
    v2 = m.group(4)
    return operation, cond, v1, v2

def index_iter(grid: List[List[int]]):
    for i,row in enumerate(grid):
        for j,cell in enumerate(row):
            yield (i+1, j+1, cell)  # 1-indexed

def calc_op(row: int, col: int, op: str):
    if op=="sum": return row + col
    if op=="product": return row * col
    if op=="difference": return abs(row-col)
    return None

# Returns lambda row,col:bool based on hint

def build_hint_checker(hint: str):
    op, cond, v1, v2 = parse_hint(hint)
    def is_even(x): return x%2==0
    def is_odd(x): return x%2==1
    def f(row,col): return True # fallback

    if cond == "is even":
        return lambda row,col: is_even(calc_op(row,col,op))
    if cond == "is odd":
        return lambda row,col: is_odd(calc_op(row,col,op))
    if cond.startswith("is less than"):
        val = int(v1)
        return lambda row,col: calc_op(row,col,op) < val
    if cond.startswith("is greater than"):
        val = int(v1)
        return lambda row,col: calc_op(row,col,op) > val
    if cond.startswith("contains digit"):
        digit = str(v1)
        return lambda row,col: digit in str(calc_op(row,col,op))
    if cond.startswith("is between"):
        low = int(v1)
        high = int(v2)
        return lambda row,col: low <= calc_op(row,col,op) <= high
    return f

# Manhattan, prefer axis

def distance_to_side(i: int, j: int, nrows: int, ncols: int, player: int):
    if player==1:
        # Left/right sides: (i,1) or (i,ncols)
        to_left = abs(j-1)
        to_right = abs(j-ncols)
        return min(to_left, to_right)
    else:
        # Top/bottom: (1,j), (nrows,j)
        to_top = abs(i-1)
        to_bottom = abs(i-nrows)
        return min(to_top, to_bottom)

# Count how close is to sides, but also outputs both distances

def both_sides_distance(i, j, nrows, ncols, player):
    if player==1:
        left = abs(j-1)
        right = abs(j-ncols)
        return left, right
    else:
        top = abs(i-1)
        bottom = abs(i-nrows)
        return top, bottom

# Returns True if this spot is adjacent (L1 or diagonal) to any player cell

def adjacent_to_own(grid, row, col, player_idx):
    n = len(grid)
    m = len(grid[0])
    for di in [-1,0,1]:
        for dj in [-1,0,1]:
            if di==0 and dj==0:
                continue
            ni = row-1 + di
            nj = col-1 + dj
            if 0<=ni<n and 0<=nj<m:
                if grid[ni][nj]==player_idx:
                    return True
    return False

def adjacent_to_opponent(grid, row, col, player_idx):
    opp = 2 if player_idx==1 else 1
    n = len(grid)
    m = len(grid[0])
    for di in [-1,0,1]:
        for dj in [-1,0,1]:
            if di==0 and dj==0:
                continue
            ni = row-1 + di
            nj = col-1 + dj
            if 0<=ni<n and 0<=nj<m:
                if grid[ni][nj]==opp:
                    return True
    return False

def select_best_position(valid_moves: List[Tuple[int,int]], current_grid, player_idx):
    n = len(current_grid)
    m = len(current_grid[0])
    opp = 2 if player_idx==1 else 1
    own_cells = [(i+1,j+1) for i in range(n) for j in range(m) if current_grid[i][j]==player_idx]
    opp_cells = [(i+1,j+1) for i in range(n) for j in range(m) if current_grid[i][j]==opp]
    # If grid is nearly empty, take central along route
    center_rows = [n//2+1, (n+1)//2]
    center_cols = [m//2+1, (m+1)//2]
    direction_priority = []
    for row,col in valid_moves:
        # 'adj_to_own' = 2 if adjacent to existing chain, 1 if own_cells non-empty and not adjacent, 0 if no own_cells
        if own_cells:
            adj_to_own = 2 if adjacent_to_own(current_grid, row, col, player_idx) else 1
        else:
            adj_to_own = 0
        # Block opponent? If adjacent to them
        adj_to_opp = 2 if adjacent_to_opponent(current_grid,row,col,player_idx) else 0
        # Distance to own win-sides
        side_dist = min(both_sides_distance(row, col, n, m, player_idx))
        # Centrality: will help in first moves
        central_bonus = 1 if (player_idx==1 and row in center_rows) or (player_idx==2 and col in center_cols) else 0
        # For player 1: prefer cells closer to left/right,  for 2: top/bottom
        key = (adj_to_own, -adj_to_opp, -central_bonus, -side_dist)
        direction_priority.append( (key, (row,col)) )
    direction_priority.sort(reverse=True)
    return direction_priority[0][1]

class SuperplyCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        current_grid = message.message[0].data[0]
        current_hint = message.message[0].data[1]
        player_idx = message.message[0].data[2]
        position_selected = None
        # Step 1: parse hint and build checker
        checker = build_hint_checker(current_hint)
        n = len(current_grid)
        m = len(current_grid[0])
        # Step 2: find all empty positions satisfying the hint
        valid_moves = []
        for i in range(n):
            for j in range(m):
                if current_grid[i][j]==0:
                    if checker(i+1,j+1):
                        valid_moves.append( (i+1, j+1) )
        # Step 3: if no valid moves, return None
        if not valid_moves:
            position_selected = None
        else:
            # Step 4: select best
            position_selected = select_best_position(valid_moves, current_grid, player_idx)
        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=position_selected, type='custom')]
        )

