        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        # current_grid is a list of lists of integers
        current_grid = message.message[0].data[0]
        # current_hint is a string
        current_hint = message.message[0].data[1]
        # player_idx is an integer: 1 or 2
        player_idx = message.message[0].data[2]
        ROWS, COLS = len(current_grid), len(current_grid[0])
        parser = HintParser(current_hint)
        valid_moves = empty_cells_with_hint(current_grid, parser)

        # Defensive: can I block the opponent's win for sure in one move?
        opp_idx = 2 if player_idx==1 else 1
        threat_moves = opponent_about_to_win(current_grid, valid_moves, opp_idx)
        if threat_moves:
            # Block the winning move
            pos = sorted(threat_moves)[0]
            position_selected = pos
        else:
            # Heuristic scoring for each move
            max_score = float('-inf')
            best_moves = []
            for mv in valid_moves:
                r,c = mv
                r0,c0 = r-1,c-1
                grcopy = [list(row) for row in current_grid]
                grcopy[r0][c0] = player_idx
                # Score 10^6 if it completes my win!
                if is_winning_path(grcopy, player_idx):
                    score = 1_000_000
                    best_moves = [mv]
                    break # Can't do better than instant win
                # Favor moves adjacent to my region (expanding my component)
                adj_bonus = 5 if neighbor_mycolor(current_grid, r0, c0, player_idx) else 0
                # Favor nearer to start edge (helps grow bridge)
                min_edist = min_edge_distance(r, c, player_idx, ROWS, COLS)
                edge_bonus = 6 - min_edist # The nearer the better for short boards
                # Center bias: value if close to center (path-likelihood for bottleneck)
                center_bias = 0
                if player_idx==1:
                    center_bias = -abs((ROWS+1)/2 - r)
                else:
                    center_bias = -abs((COLS+1)/2 - c)
                score = adj_bonus + edge_bonus + center_bias
                # Small anti-clumping: randomize tie-breaks
                score += random.uniform(-0.01,0.01)
                if score > max_score:
                    max_score = score
                    best_moves = [mv]
                elif abs(score - max_score) < 1e-7:
                    best_moves.append(mv)
            if best_moves:
                position_selected = sorted(best_moves)[0]
            else:
                # Should not really happen: pick any valid
                position_selected = valid_moves[0] if valid_moves else (1,1)

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=position_selected, type='custom')]
        )

