def parse_hint(hint):
    # E.g. "sum is less than 10" => op: sum, cond: is less than 10
    ops = ['sum', 'product', 'difference']
    op = None
    for o in ops:
        if hint.startswith(o):
            op = o
            rest = hint[len(o):].strip()
            break
    if not op:
        raise ValueError(f"Unknown operation in hint: {hint}")
    # try to extract numbers (for 'between v1 and v2' cases, etc)
    numbers = list(map(int, re.findall(r'\d+', rest)))
    return op, rest, numbers

def cell_value(row, col, op):
    if op == 'sum':
        return row + col
    elif op == 'product':
        return row * col
    elif op == 'difference':
        return abs(row - col)
    else:
        raise ValueError(f"Unknown op: {op}")

def satisfies_condition(op, cond, nums, row, col):
    v = cell_value(row, col, op)
    if 'is less than' in cond:
        return v < nums[0]
    elif 'is greater than' in cond:
        return v > nums[0]
    elif 'contains digit' in cond:
        return str(nums[0]) in str(v)
    elif 'is even' in cond:
        return v % 2 == 0
    elif 'is odd' in cond:
        return v % 2 == 1
    elif 'is between' in cond:
        # between v1 and v2, inclusive
        return nums[0] <= v <= nums[1]
    else:
        raise ValueError(f"Unknown condition: {cond}")

def get_valid_moves(current_grid, op, cond, nums):
    n = len(current_grid)
