        v1 = int(condition.split()[-1])
        return (operation, 'lt', v1)
    elif condition.startswith('is greater than'):
        v1 = int(condition.split()[-1])
        return (operation, 'gt', v1)
    elif condition.startswith('contains digit'):
        v1 = int(condition.split()[-1])
        return (operation, 'contains_digit', v1)
    elif condition.startswith('is even'):
        return (operation, 'even', None)
    elif condition.startswith('is odd'):
        return (operation, 'odd', None)
    elif condition.startswith('is between'):
        match = re.search(r'is between (\d+) and (\d+), inclusive', condition)
        if match:
            v1 = int(match.group(1))
            v2 = int(match.group(2))
            return (operation, 'between', (v1, v2))
    return None

def operation_func(row: int, col: int, op: str) -> int:
    if op == 'sum':
        return row + col
    elif op == 'product':
        return row * col
    elif op == 'difference':
        return abs(row - col)
    else:
        return 0

def satisfies_condition(value: int, cond: str, v):
    if cond == 'lt':
        return value < v
    elif cond == 'gt':
        return value > v
    elif cond == 'contains_digit':
        return str(v) in str(value)
    elif cond == 'even':
        return value % 2 == 0
    elif cond == 'odd':
        return value % 2 == 1
    elif cond == 'between':
        v1, v2 = v
        return v1 <= value <= v2
    else:
        return False

