# --- Helper Functions ---
def parse_hint(hint):
    # Examples: sum is less than 6, product contains digit 6, difference is even, sum is between 3 and 10, inclusive
    oper = None
    cond = None
    v1 = None
    v2 = None
    # operation
    if hint.startswith('sum '):
        oper = 'sum'
        rest = hint[4:]
    elif hint.startswith('product '):
        oper = 'product'
        rest = hint[8:]
    elif hint.startswith('difference '):
        oper = 'difference'
        rest = hint[11:]
    else:
        return None
    rest = rest.strip()
    # Condition
    if rest.startswith('is less than'):
        cond = 'is less than'
        v1 = int(re.findall(r'is less than (\d+)', rest)[0])
    elif rest.startswith('is greater than'):
        cond = 'is greater than'
        v1 = int(re.findall(r'is greater than (\d+)', rest)[0])
    elif rest.startswith('contains digit'):
        cond = 'contains digit'
        v1 = int(re.findall(r'contains digit (\d+)', rest)[0])
    elif rest.startswith('is even'):
