    elif rest.startswith('is odd'):
        cond = 'is odd'
    elif rest.startswith('is between'):
        match = re.findall(r'is between (\d+) and (\d+), inclusive', rest)
        if match and len(match[0])==2:
            cond = 'is between'
            v1 = int(match[0][0])
            v2 = int(match[0][1])
    else:
        return None
    return {'oper':oper, 'cond':cond, 'v1':v1, 'v2':v2}

def get_value(oper, r, c):
