    elif oper=='product': return r*c
    elif oper=='difference': return abs(r-c)
    return None

def check_hint(parsed_hint, r, c):
    val = get_value(parsed_hint['oper'], r, c)
    if parsed_hint['cond']=='is less than':
        return val < parsed_hint['v1']
    elif parsed_hint['cond']=='is greater than':
        return val > parsed_hint['v1']
    elif parsed_hint['cond']=='contains digit':
        return str(parsed_hint['v1']) in str(val)
    elif parsed_hint['cond']=='is even':
        return val%2==0
    elif parsed_hint['cond']=='is odd':
        return val%2==1
    elif parsed_hint['cond']=='is between':
