# --- HINT INTERPRETER ---
def parse_hint(hint: str):
    # Possible forms:
    #   "sum is less than 6" -> ('sum', 'is less than', 6)
    #   "product is between 3 and 5, inclusive" -> ('product', 'is between', 3, 5)
    #   "difference is even" -> ('difference', 'is even')
    #   "sum contains digit 2" -> ('sum', 'contains digit', 2)
    #   "product is odd" -> ('product', 'is odd')
    ops = ['sum', 'product', 'difference']
    conds = ['is less than', 'is greater than', 'contains digit', 'is even', 'is odd', 'is between']

    op = None
    for o in ops:
        if hint.startswith(o):
            op = o
            break
    if op is None:
        return None
    rest = hint[len(op):].strip()

    # TLDR, match most specific first
    if rest.startswith('is less than'):
        v = int(rest[len('is less than'):].strip())
        return (op, 'is less than', v)
    if rest.startswith('is greater than'):
        v = int(rest[len('is greater than'):].strip())
        return (op, 'is greater than', v)
    if rest.startswith('contains digit'):
        v = int(rest[len('contains digit'):].strip())
        return (op, 'contains digit', v)
    if rest.startswith('is even'):
        return (op, 'is even')
    if rest.startswith('is odd'):
        return (op, 'is odd')
    if rest.startswith('is between'):
        match = re.match(r'is between (\d+) and (\d+), inclusive', rest)
        if match:
            v1 = int(match.group(1))
            v2 = int(match.group(2))
            return (op, 'is between', v1, v2)
    return None

# --- HINT CHECKER ---
def check_hint(row, col, parsed_hint):
    # indices 1-based
    op = parsed_hint[0]
    cond = parsed_hint[1]
    if op == 'sum':
        v = row + col
    elif op == 'product':
        v = row * col
    elif op == 'difference':
        v = abs(row - col)

    if cond == 'is less than':
        return v < parsed_hint[2]
    if cond == 'is greater than':
        return v > parsed_hint[2]
    if cond == 'contains digit':
        return str(parsed_hint[2]) in str(v)
    if cond == 'is even':
        return v % 2 == 0
    if cond == 'is odd':
        return v % 2 == 1
    if cond == 'is between':
        return parsed_hint[2] <= v <= parsed_hint[3]
    return False

