            score += 0.3 * center_weight
        else: # player_idx == 2
            proximity = min(r-1, nrows-r)
            score -= 0.3*proximity
            if r==1 or r==nrows:
                score += 1.1
            if adjacent_to_group((r, c), own_positions):
                score += 1.2
            center_weight = 1 - abs(c - (ncols+1)//2)/(ncols/2)
            score += 0.3 * center_weight
        # Block opponent: if adjacent to opponent, some value
        if adjacent_to_group((r, c), opp_positions):
