from system.message import Info
from system.message import BaseMessageDataType
from model.strategy_type import StrategyType
from model.base import BaseStrategy

import re
import random

class SuperplyCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        current_grid = message.message[0].data[0]
        current_hint = message.message[0].data[1]
        player_idx = message.message[0].data[2]

        # --------- Helper Functions ----------
        def parse_hint(hint):
            op = cond = None
            v1 = v2 = None
            # Supported: 'sum', 'product', 'difference'
            if hint.startswith('sum '):
                op = 'sum'
                cond_str = hint[4:].strip()
            elif hint.startswith('product '):
                op = 'product'
                cond_str = hint[8:].strip()
            elif hint.startswith('difference '):
                op = 'difference'
                cond_str = hint[11:].strip()
            else:
                return None, None, None, None
            # Parse conditions
            if 'is less than' in cond_str:
                m = re.search(r'is less than (\d+)', cond_str)
                cond = 'is less than'
                v1 = int(m.group(1))
            elif 'is greater than' in cond_str:
                m = re.search(r'is greater than (\d+)', cond_str)
                cond = 'is greater than'
                v1 = int(m.group(1))
            elif 'contains digit' in cond_str:
                m = re.search(r'contains digit (\d)', cond_str)
                cond = 'contains digit'
                v1 = m.group(1)
            elif 'is even' in cond_str:
                cond = 'is even'
            elif 'is odd' in cond_str:
                cond = 'is odd'
            elif 'is between' in cond_str:
                m = re.search(r'is between (\d+) and (\d+), inclusive', cond_str)
                cond = 'is between'
                v1 = int(m.group(1))
                v2 = int(m.group(2))
            else:
                cond = None
            return op, cond, v1, v2

        def compute_val(r, c, op):
            if op == 'sum':
                return r + c
            elif op == 'product':
                return r * c
            elif op == 'difference':
                return abs(r - c)
            return None

        def matches_condition(val, cond, v1, v2):
            if cond == 'is less than':
                return val < v1
            if cond == 'is greater than':
                return val > v1
            if cond == 'contains digit':
                return v1 in str(val)
            if cond == 'is even':
                return val % 2 == 0
            if cond == 'is odd':
                return val % 2 == 1
            if cond == 'is between':
                return v1 <= val <= v2
            return False

        def legal_positions(gr, op, cond, v1, v2):
            N = len(gr)
            M = len(gr[0])
            res = []
            for i in range(N):
                for j in range(M):
                    if gr[i][j] != 0:
                        continue
                    # 1-indexed
                    r, c = i+1, j+1
                    val = compute_val(r, c, op)
                    if val is None:
                        continue
                    if matches_condition(val, cond, v1, v2):
                        res.append( (i, j) )
            return res

        def my_cells(gr, player_val):
            cells = []
            for i, row in enumerate(gr):
                for j, v in enumerate(row):
                    if v == player_val:
                        cells.append( (i, j) )
            return cells

        def is_adjacent(a, b):
            dx = abs(a[0]-b[0])
            dy = abs(a[1]-b[1])
            return (dx <= 1 and dy <= 1) and (dx + dy > 0)

        def adjacents_to_my_cells(cands, mycells):
            adj = set()
            for cell in mycells:
                for pos in cands:
                    if is_adjacent(cell, pos):
                        adj.add(pos)
            return list(adj)

        # Preference scoring: encourage move towards my side
        def candidate_score(pos, N, M, player_idx):
            i,j = pos
            # 0-indexed
            if player_idx == 1:
                # prefer cols 0 or M-1
                dist_left = j
                dist_right = M-1 - j
                return -min(dist_left, dist_right), -abs(i - N//2)
            else:
                # prefer rows 0 or N-1
                dist_top = i
                dist_bot = N-1 - i
                return -min(dist_top, dist_bot), -abs(j - M//2)

        def break_ties(candidates, N, M, player_idx):
            # Return the best by score
            scored = [(candidate_score(pos, N, M, player_idx), pos) for pos in candidates]
