# For superply, extend path if possible - look for adjacent to existing, else take on edge toward target side.
def strategic_choice(grid, valid, player_idx):
    n = len(grid)
    m = len(grid[0])
    clusters = find_clusters(grid, player_idx)
    # player1: left to right. player2: top to bottom.
    if player_idx == 1:
        primary_edge = 'left'
        secondary_edge = 'right'
        # try to extend towards right
        direction = 'horizontal'
    else:
        primary_edge = 'top'
        secondary_edge = 'bottom'
        direction = 'vertical'
    # Score by whether the move connects to existing cluster
    cluster_squares = set()
    for cl in clusters:
        for pos in cl:
            cluster_squares.add(pos)
    best_path_move = None
    min_dist = 1e9
    best_edge_move = None
    best_edge_dist = 1e9
    # Score for making bridge between sides
    for vr, vc in valid:
