            dt = dist_to_sides(vr, vc, n, m, secondary_edge)
            if dt < min_dist:
                best_path_move = (vr, vc)
                min_dist = dt
        # fallback: find valid move closest to primary edge (starting move)
        dprim = dist_to_sides(vr, vc, n, m, primary_edge)
