        (r'^(sum|product|difference) contains digit (\d)$', lambda x: (x[0], 'contains digit', int(x[1]), None)),
        (r'^(sum|product|difference) is even$', lambda x: (x[0], 'is even', None, None)),
        (r'^(sum|product|difference) is odd$', lambda x: (x[0], 'is odd', None, None)),
        (r'^(sum|product|difference) is between (\d+) and (\d+), inclusive$', lambda x: (x[0], 'is between', int(x[1]), int(x[2]))),
